```java
@Service
public class S3StorageService {
    private final S3Client s3Client;
    private final String bucketName;

    public S3StorageService(S3Client s3Client,
                            @Value("${aws.s3.bucket}") String bucketName) {
        this.s3Client = s3Client;
        this.bucketName = bucketName;
    }

    public String uploadFile(String key, byte[] content, String contentType) {
        PutObjectRequest req = PutObjectRequest.builder()
            .bucket(bucketName)
            .key(key)
            .contentType(contentType)
            .build();

        s3Client.putObject(req, RequestBody.fromBytes(content));
        return "https://" + bucketName + ".s3.amazonaws.com/" + key;
    }

    public byte[] downloadFile(String key) {
        GetObjectRequest req = GetObjectRequest.builder()
            .bucket(bucketName)
            .key(key)
            .build();
        return s3Client.getObjectAsBytes(req).asByteArray();
    }

    public void deleteFile(String key) {
        s3Client.deleteObject(b -> b.bucket(bucketName).key(key));
    }
}
```

## Presigned URLs — Temporary Access

```java
public String generatePresignedUploadUrl(String key, Duration expiry) {
    try (S3Presigner presigner = S3Presigner.builder()
            .region(Region.AP_SOUTH_1).build()) {

        PutObjectPresignRequest req = PutObjectPresignRequest.builder()
            .signatureDuration(expiry)
            .putObjectRequest(b -> b.bucket(bucketName).key(key))
            .build();

        return presigner.presignPutObject(req).url().toString();
        // Client uploads directly to S3 — never passes through your server!
    }
}

public String generatePresignedDownloadUrl(String key, Duration expiry) {
    try (S3Presigner presigner = S3Presigner.builder().build()) {
        return presigner.presignGetObject(b ->
            b.signatureDuration(expiry)
             .getObjectRequest(r -> r.bucket(bucketName).key(key))
        ).url().toString();
    }
}
```

