func twoSum(nums []int, target int) []int {
  seen := map[int]int{}
  for i, n := range nums {
    if j, ok := seen[target-n]; ok { return []int{j, i} }
    seen[n] = i
  }
  return nil
}
```

// HashMap — your default choice
Map<String, Integer> scores = new HashMap<>();
scores.put(null, 100);        // OK — one null key allowed
