// RUNTIME POLYMORPHISM in action — strategy pattern
public interface DiscountStrategy {
    double apply(double price);
}

public class PercentageDiscount implements DiscountStrategy {
    private final double percent;
    public PercentageDiscount(double percent) { this.percent = percent; }

    @Override
    public double apply(double price) {
        return price * (1 - percent / 100);  // 20% off → price * 0.8
    }
}

public class FlatDiscount implements DiscountStrategy {
    private final double amount;
    public FlatDiscount(double amount) { this.amount = amount; }

    @Override
    public double apply(double price) {
        return Math.max(0, price - amount);  // subtract flat amount
    }
}

// Usage — caller doesn't know which strategy is used
public double checkout(double price, DiscountStrategy strategy) {
    return strategy.apply(price);  // polymorphic dispatch
}

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
public class BankTransferService {
    private final AccountRepository accountRepo;

    public BankTransferService(AccountRepository accountRepo) {
        this.accountRepo = accountRepo;
    }

    @Transactional  // ACID wrapper: all four properties enforced
    public void transfer(Long fromId, Long toId, BigDecimal amount) {
        var fromAccount = accountRepo.findById(fromId).orElseThrow();
        var toAccount = accountRepo.findById(toId).orElseThrow();

        fromAccount.debit(amount);  // Atomicity: both or neither
        toAccount.credit(amount);

        accountRepo.save(fromAccount);  // Consistency: constraints checked
        accountRepo.save(toAccount);    // Isolation: locked from other txns
        // Durability: committed to WAL before returning
    }
}

