// Conceptual shard routing in Java
public class ShardRouter {
    private static final int SHARD_COUNT = 4;
    private final Map<Integer, DataSource> shards;

    // Hash-based shard key on userId
    public DataSource getShardForUser(long userId) {
        int shardId = (int) (userId % SHARD_COUNT);
        return shards.get(shardId);
    }

    // Range-based shard key on created_date
    // Shard 0: 2020, Shard 1: 2021, Shard 2: 2022, Shard 3: 2023+
    public DataSource getShardForOrder(LocalDate createdDate) {
        int year = createdDate.getYear();
        int shardId = Math.min(year - 2020, SHARD_COUNT - 1);
        return shards.get(shardId);
    }
}

// Spring AbstractRoutingDataSource for transparent shard routing
public class ShardingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        // Set via ThreadLocal before each request
        return ShardContext.getCurrentShardId();
    }
}

// Anti-pattern: cross-shard join (avoid at all costs)
// SELECT * FROM shard1.orders o JOIN shard2.customers c ON o.customer_id = c.id
// Requires application-level join across multiple network calls

// 1. ThreadLocal key holder
public class DataSourceContextHolder {
    private static final ThreadLocal<String> context = new ThreadLocal<>();
    public static void setDataSourceType(String type) { context.set(type); }
    public static String getDataSourceType() { return context.get(); }
    public static void clear() { context.remove(); }
}

// 2. Routing DataSource
public class RoutingDataSource extends AbstractRoutingDataSource {
    @Override
    protected Object determineCurrentLookupKey() {
        return DataSourceContextHolder.getDataSourceType();
    }
}

// 3. DataSource configuration
@Configuration
public class DataSourceConfig {
    @Bean
    @ConfigurationProperties("spring.datasource.primary")
    public DataSource primaryDataSource() { return DataSourceBuilder.create().build(); }

    @Bean
    @ConfigurationProperties("spring.datasource.replica")
    public DataSource replicaDataSource() { return DataSourceBuilder.create().build(); }

    @Bean @Primary
    public DataSource routingDataSource(
            @Qualifier("primaryDataSource") DataSource primary,
            @Qualifier("replicaDataSource") DataSource replica) {
        RoutingDataSource rds = new RoutingDataSource();
        Map<Object, Object> sources = new HashMap<>();
        sources.put("primary", primary);
        sources.put("replica", replica);
        rds.setTargetDataSources(sources);
        rds.setDefaultTargetDataSource(primary);
        return rds;
    }
}

// 4. Read-your-writes guard: route reads to primary briefly after a write
@Aspect @Component
public class DataSourceRoutingAspect {
    @Around("@annotation(org.springframework.transaction.annotation.Transactional)")
    public Object route(ProceedingJoinPoint pjp) throws Throwable {
        Transactional tx = ((MethodSignature) pjp.getSignature())
            .getMethod().getAnnotation(Transactional.class);
        boolean readOnly = tx != null && tx.readOnly();
        String key = readOnly && !RecentWriteMarker.isRecent() ? "replica" : "primary";
        DataSourceContextHolder.setDataSourceType(key);
        try { return pjp.proceed(); }
        finally { DataSourceContextHolder.clear(); }
    }
}

