import java.util.concurrent.*;

// (1) Callable returns a value; Runnable does not.
Callable<Integer> task = () -> {
    Thread.sleep(1000);
    return 42;                       // returns Integer, can throw checked exc
};

// (2) Submit to an ExecutorService -> get a Future.
ExecutorService pool = Executors.newFixedThreadPool(2);
Future<Integer> future = pool.submit(task);

// (3) Retrieve the result. get() BLOCKS until ready.
while (!future.isDone()) { /* do other work, don't block yet */ }
Integer result = future.get();      // blocks here if not already done
System.out.println(result);         // 42
future.cancel(true);                // cancel a still-running task (interrupt)
pool.shutdown();
```

```java
// (1) EXTEND Thread (works, but ties you to a single execution).
class MyThread extends Thread {
  public void run() { System.out.println("running on " + getName()); }
}
new MyThread().start();

// (2) IMPLEMENT Runnable (PREFERRED: task separate from execution).
Runnable task = () -> System.out.println("running on " + Thread.currentThread());
new Thread(task).start();

// (3) PRACTICE: use an ExecutorService (pools threads, don't create directly).
ExecutorService pool = Executors.newFixedThreadPool(4);
pool.submit(task);                 // reuse a pooled thread
pool.submit(task);
pool.shutdown();                   // always shut down

// (4) MODERN: virtual threads (Project Loom) for lightweight I/O concurrency.
Thread.startVirtualThread(task);   // millions of cheap threads
```

```java
// (1) SYNCHRONIZED METHOD: locks the whole method on `this`. Coarse.
public synchronized void increment() { count++; }
//   Equivalent to: synchronized(this) { count++; }
//   Problem: callers can also lock on `this` -> deadlock risk; long method
//   holds the lock a long time.

// (2) SYNCHRONIZED BLOCK: locks only the critical region on a PRIVATE lock.
private final Object lock = new Object();
public void increment() {
  // ... other non-critical work that DOESN'T need the lock ...
  synchronized (lock) {            // fine-grained, private lock
    count++;
  }
}
//   Benefits: only the critical region is locked; the lock is private so
//   callers can't lock on it -> safer; better throughput.
```

```java
// (1) RACE CONDITION: two threads increment a shared counter unsafely.
int count = 0;
Runnable inc = () -> { for (int i = 0; i < 10000; i++) count++; };
Thread t1 = new Thread(inc), t2 = new Thread(inc);
t1.start(); t2.start(); t1.join(); t2.join();
//   count is likely < 20000 — lost updates (count++ is read+add+write, not atomic).
//   FIX: synchronize, or use AtomicInteger.

// (2) DEADLOCK: two threads each hold a lock the other needs.
Object a = new Object(), b = new Object();
new Thread(() -> { synchronized(a){ synchronized(b){ /* ... */ } } }).start();
new Thread(() -> { synchronized(b){ synchronized(a){ /* ... */ } } }).start();
//   t1 holds a, waits for b; t2 holds b, waits for a -> deadlock.
//   FIX: always lock in a consistent order (a then b).
```

```java
// PROCESS: separate memory. Two JVMs don't share heap objects.
//   Process A: java -jar app.jar     <- its own heap
//   Process B: java -jar app.jar     <- its own heap; no shared objects
//   To share data they need IPC (sockets, files, queues).

// THREAD: shares the process's memory (heap).
Runnable shared = () -> {
  // runs on a new thread but sees the SAME `list` as the main thread.
  list.add("from thread " + Thread.currentThread().getName());
};
new Thread(shared).start();
list.add("from main");
//   Easy sharing, but list is not thread-safe -> needs synchronization.
